var n=`0903-gulha`;var t=`world-0903`;var a=`MV`;var s=`south-asia`;var o=4;var d=63;var r={en:`Gulha`,ua:`Гулга`};var l={en:`Gulha is a Maldives dish made with all-purpose flour, canned tuna, desiccated coconut, red onion. This home-scale recipe assigns measured ingredients to the steps where they are used. Canned tuna replaces Maldivian smoked fish.`,ua:`Гулга, страва кухні країни Мальдіви. Основні складники: пшеничне борошно універсальне, консервований тунець, кокосова стружка, червона цибуля. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів. Консервований тунець замінює мальдівську копчену рибу.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 16 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 16 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:16,i:[[`all-purpose-flour`,320,`g`],[`water`,180,`ml`],[`table-salt`,5,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`canned-tuna`,260,`g`],[`desiccated-coconut`,85,`g`],[`red-onion`,125,`g`],[`bird-s-eye-chili`,2,`pcs`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:18,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 17 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 17 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:17,i:[[`coconut-oil`,600,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lime`,1,`pcs`]]}];var h={slug:n,id:t,country:`MV`,region:s,servings:4,minutes:63,title:r,text:l,steps:u};export{a as country,h as default,t as id,d as minutes,s as region,o as servings,n as slug,u as steps,l as text,r as title};